offloading:
firewall.@defaults[0].flow_offloading='1'
firewall.@defaults[0].flow_offloading_hw='1'
table inet fw4 {
	flowtable ft {
		hook ingress priority filter
		devices = { lan1, lan2, lan3, phy0-ap0, phy1-ap0, phy1-sta0, pppoe-wan, wgdorm }
		flags offload
		counter
	}
}
table inet dnsmasq {
}
